def write_group(folder: str, samples: dict, label: str, lang: str, extra: dict) -> list:
    os.makedirs(folder, exist_ok=True)
    meta = []
    for name, text in samples.items():
        path = os.path.join(folder, name + ".txt")
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text.strip() + "\n")
        rec = {
            "file": name + ".txt",
            "label": label,
            "lang": lang,
            "chars": len(text.strip()),
        }
        rec.update(extra)
        meta.append(rec)
    with open(os.path.join(folder, "_meta.json"), "w", encoding="utf-8") as fh:
        json.dump(meta, fh, ensure_ascii=False, indent=2)
    return meta


def main() -> None:
    root = os.path.dirname(os.path.abspath(__file__))
    m1 = write_group(
        os.path.join(root, "ai_en"), AI_EN, "ai", "en",
        {
            "provenance": "AI-generated calibration sample (LLM output)",
            "generator": "assistant-llm",
            "note": "written by the assistant that built this tool; real model output, not synthetic noise",
        },
    )
    m2 = write_group(
        os.path.join(root, "ai_zh"), AI_ZH, "ai", "zh",
        {
            "provenance": "AI-generated calibration sample (LLM output)",
            "generator": "assistant-llm",
            "note": "written by the assistant that built this tool; real model output, not synthetic noise",
        },
    )
    m3 = write_group(
        os.path.join(root, "human_zh"), HUMAN_ZH, "human", "zh",
        {
            "provenance": "real human writing (user's own draft)",
            "license": "provided by user",
            "note": "PROVISIONAL: only one built-in Chinese human sample. Add your own drafts "
                    "to calib/human_zh/ and re-run calibrate.py; Chinese-side anchors are "
                    "flagged low-confidence until >= 5 human samples exist.",
        },
    )
    print(f"ai_en={len(m1)} ai_zh={len(m2)} human_zh={len(m3)}")


if __name__ == "__main__":
    main()
